body{margin:0;font-family:"Open Sans","Inter","Segoe UI",Arial,sans-serif;color:#e2e8f0;background:#0f172a;}
.mwrap{position:relative;display:flex;flex-direction:column;height:100%;background:#0f172a;padding:22px 26px;box-sizing:border-box;overflow:auto;}
.mhead{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:14px;padding-right:36px;}
.mtitle{font-size:18px;font-weight:700;color:#f1f5f9;margin:0;}
.mx{position:absolute;top:16px;right:18px;z-index:10;background:transparent;border:none;color:#cbd5e1;font-size:26px;line-height:1;cursor:pointer;padding:2px 8px;border-radius:6px;}
.mx:hover{color:#ffffff;background:#334155;}
.mp{color:#cbd5e1;font-size:14px;line-height:1.5;margin:0 0 12px;}
.mol{color:#cbd5e1;font-size:14px;line-height:1.6;margin:0 0 14px;padding-left:20px;}
.dl{display:inline-flex;align-items:center;gap:6px;color:#60a5fa;text-decoration:underline;font-size:14px;cursor:pointer;margin:6px 0 18px;}
.drop{display:flex;align-items:center;gap:12px;margin-bottom:22px;}
.dropbox{flex:1;border:1px solid #334155;border-radius:6px;padding:12px 14px;color:#64748b;font-size:14px;background:#1e293b;}
.browse{color:#60a5fa;font-weight:600;font-size:14px;cursor:pointer;}
.foot{display:flex;justify-content:center;gap:14px;margin-top:auto;padding-top:10px;}
.btn{padding:10px 22px;border-radius:6px;font-size:14px;font-weight:600;cursor:pointer;border:1px solid #334155;}
.btn.cancel{background:transparent;color:#e2e8f0;}
.btn.cancel:hover{background:#1e293b;}
.btn.primary{background:#2563eb;color:#ffffff;border-color:#2563eb;}
.btn.primary:hover{background:#1d4ed8;}
.card{background:#1e293b;border:1px solid #334155;border-radius:8px;padding:16px 18px;margin-bottom:18px;}
.card h4{margin:0 0 12px;font-size:15px;font-weight:700;color:#f1f5f9;}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px 24px;}
.f{display:flex;gap:10px;font-size:13px;}
.f .lbl{color:#94a3b8;min-width:120px;}
.f .val{color:#e2e8f0;font-weight:600;}
.sec{font-size:14px;font-weight:700;color:#f1f5f9;margin:6px 0 10px;}
.zerobox{background:#1e293b;border:1px solid #334155;border-radius:6px;padding:16px;text-align:center;color:#94a3b8;font-size:14px;margin-bottom:18px;}
.msearch{width:100%;box-sizing:border-box;padding:10px 12px 10px 34px;border:1px solid #334155;border-radius:6px;background:#1e293b url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='15' height='15' viewBox='0 0 24 24' fill='none' stroke='%2394a3b8' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='11' cy='11' r='8'/><line x1='21' y1='21' x2='16.65' y2='16.65'/></svg>") no-repeat 10px center;color:#e2e8f0;font-size:14px;outline:none;margin-bottom:16px;}
.opt{display:flex;align-items:center;gap:10px;background:#1e293b;border:1px solid #334155;border-radius:6px;padding:12px 14px;margin-bottom:10px;color:#e2e8f0;font-size:14px;cursor:pointer;}
.opt input{accent-color:#2563eb;width:16px;height:16px;}
.openrow{display:flex;align-items:center;gap:14px;margin:14px 0 4px;color:#cbd5e1;font-size:14px;}
.dateinp{padding:9px 12px;border:1px solid #334155;border-radius:6px;background:#1e293b;color:#e2e8f0;font-size:14px;outline:none;}
.ro{font-size:12px;color:#f59e0b;margin-left:10px;}

