import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";
function App(){
  const close=()=>{ if(typeof appsmith.triggerEvent==="function") appsmith.triggerEvent("onClose"); };
  const upload=()=>{ if(typeof appsmith.triggerEvent==="function") appsmith.triggerEvent("onUpload"); };
  return React.createElement("div",{className:"mwrap"},
    React.createElement("div",{className:"mhead"},
      React.createElement("h3",{className:"mtitle"},"Bulk Map Virtual Accounts"),
      React.createElement("button",{className:"mx",onClick:close},"\u00D7")),
    React.createElement("p",{className:"mp"},"Map multiple or all unmapped Virtual Accounts to locations:"),
    React.createElement("ol",{className:"mol"},
      React.createElement("li",null,"Download the list from the link below"),
      React.createElement("li",null,"Populate the list with the Location ID/s where you want to map the Virtual Account/s (1 Location ID per Account)"),
      React.createElement("li",null,"Browse or drag&drop the updated template in the field below, and select the Upload button")),
    React.createElement("p",{className:"mp"},"Due to the fact that the file verification and mapping can take from a few seconds to a few minutes, depending on the number of virtual accounts that need to be mapped, an email will be sent out to you with the outcome when the process is done."),
    React.createElement("a",{className:"dl",onClick:()=>appsmith.triggerEvent("onUpload")},"Download \u201CMap Virtual Accounts List in bulk\u201D \u24D8"),
    React.createElement("div",{className:"drop"},
      React.createElement("div",{className:"dropbox"},"Browse or drag&drop the updated Template"),
      React.createElement("span",{className:"browse",onClick:upload},"+Browse")),
    React.createElement("div",{className:"foot"},
      React.createElement("button",{className:"btn cancel",onClick:close},"Cancel"),
      React.createElement("button",{className:"btn primary",onClick:upload},"Upload"),
      React.createElement("span",{className:"ro"},"Read-only view")));
}
ReactDOM.render(React.createElement(App,null),document.getElementById("root"));

